def _box(x0, x1, y0, y1, z0, z1):
    return Solid.makeBox(x1 - x0, y1 - y0, z1 - z0, Vector(x0, y0, z0))

def _zcyl(r, x, y, z0, z1):
    return Solid.makeCylinder(r, z1 - z0, Vector(x, y, z0), Vector(0, 0, 1))

def _xcyl(r, y, z, x0, x1):
    return Solid.makeCylinder(r, x1 - x0, Vector(x0, y, z), Vector(1, 0, 0))

def _ycyl(r, x, z, y0, y1):
    return Solid.makeCylinder(r, y1 - y0, Vector(x, y0, z), Vector(0, 1, 0))
s = _box(0, 128.2, 0, 51.6, 0, 4.3)
tri = cq.Workplane("XY").polyline([(13.1, 8.8), (29.1, 8.8), (21.1, 42.8)]).close().extrude(4.3).val()
s = s.cut(tri)
tri = cq.Workplane("XY").polyline([(41.8, 42.8), (57.8, 42.8), (49.8, 8.8)]).close().extrude(4.3).val()
s = s.cut(tri)
tri = cq.Workplane("XY").polyline([(70.4, 8.8), (86.4, 8.8), (78.4, 42.8)]).close().extrude(4.3).val()
s = s.cut(tri)
tri = cq.Workplane("XY").polyline([(99.1, 42.8), (115.1, 42.8), (107.1, 8.8)]).close().extrude(4.3).val()
s = s.cut(tri)
result = s

